body.ot-navigation .sidebar-brand small{font-size:11px}
body.ot-navigation .ot-main-nav{display:flex!important;flex-direction:column!important;gap:6px;position:static!important;width:100%;height:auto;overflow:visible}
body.ot-navigation .ot-main-nav .nav-btn{display:flex!important;align-items:center;justify-content:flex-start!important;gap:7px;min-height:46px;width:100%;padding:10px 8px;text-align:left;font-size:13px;line-height:1.3;white-space:nowrap;border-radius:9px}
