body.ot-navigation .ot-main-nav i{font-style:normal;width:19px;flex:none;font-size:18px}
body.ot-navigation .topbar{grid-column:2;grid-row:1;position:sticky!important;top:var(--ot-top)!important;left:auto!important;right:auto!important;display:flex!important;flex-wrap:wrap;gap:10px!important;padding:12px 20px!important;margin:0!important;width:100%;min-width:0;z-index:46;background:var(--bg,#101114);border-radius:0!important}
body.ot-navigation .topbar>.brand,body.ot-navigation .trainer-top-brand{display:none!important}
body.ot-navigation .topbar-controls{display:flex!important;flex-wrap:wrap;gap:6px;justify-content:flex-end;order:2;max-width:100%;min-width:0;margin-left:auto}
body.ot-navigation .topbar-controls button,body.ot-navigation .topbar-controls summary{min-height:36px;font-size:12px;padding:7px 10px;white-space:nowrap}
body.ot-navigation .ot-members-search{display:flex!important;flex-direction:column;align-items:stretch;gap:4px;flex:1 1 320px;order:1;min-width:200px;max-width:none!important;margin:0!important;position:relative}
body.ot-navigation .ot-members-search>span{font-weight:700;font-size:13px}
body.ot-navigation .ot-members-search input{width:100%;min-height:42px;max-width:none}
body.ot-navigation .members-search-results{position:absolute;top:100%;left:0;width:100%;min-width:0;max-width:100%;max-height:50vh;z-index:70}
body.ot-navigation .content{grid-column:2;grid-row:2;padding:18px 20px!important;margin:0!important;min-width:0;width:100%;max-width:none!important}
body.ot-navigation .content>.view{max-width:none!important;width:100%;min-width:0}
body.ot-navigation .ot-hidden-context,body.ot-navigation .ot-dashboard-legacy{display:none!important}
body.ot-navigation .ot-quick-actions,body.ot-navigation .ot-member-filters [role=group]{display:flex;flex-wrap:wrap;gap:10px}
body.ot-navigation [data-ot-member-filter][aria-pressed=true]{border-color:#d4a64c;background:#d4a64c22;color:#f1cd7d}
body.ot-navigation #clientCards .client-card[hidden]{display:none!important}
body.ot-navigation #clients>.split-layout{display:block}
body.ot-navigation #clients>#goalForm{display:none!important}
body.ot-navigation #clients.members-profile-active{margin:0;padding:0}
body.ot-navigation .members-profile-page{width:100%!important;max-width:none!important;max-height:none!important;min-width:0;margin:0;padding:18px;overflow:visible}
body.ot-navigation .members-profile-tabs{display:flex;flex-wrap:wrap;gap:5px;overflow:visible;width:100%;max-width:100%;padding:8px 0 12px}
body.ot-navigation .members-profile-tabs [role=tab]{flex:1 0 auto;min-width:0;padding:9px 6px;font-size:12px;min-height:42px;line-height:1.3;white-space:nowrap}
body.ot-navigation .ot-member-component.view{display:block!important;margin:0;padding:0}
body.ot-navigation .ot-member-component>.view-head{display:none}
body.ot-navigation .ot-member-component{max-width:100%;min-width:0}
body.ot-navigation .ot-builder-assignment{display:grid;gap:14px;margin-bottom:20px}
body.ot-navigation .ot-builder-assignment label{max-width:640px}
body.ot-navigation .ot-selected-member{display:flex;align-items:center;gap:12px;padding:14px;border:1px solid #bd9546;border-radius:10px}
body.ot-navigation .ot-selected-member small{display:block;margin-top:6px}
body.ot-navigation .ot-selected-member img{width:48px;height:48px;object-fit:cover;border-radius:50%}
body.ot-navigation .ot-builder-assignment button{white-space:normal}
body.ot-navigation.ot-builder-active #trainingCopyPanel,body.ot-navigation.ot-builder-active [data-publish-training],body.ot-navigation.ot-builder-active #trainingGoalStrip,body.ot-navigation.ot-builder-active [data-training-log],body.ot-navigation.ot-builder-active #training .exercise-log,body.ot-navigation.ot-builder-active [data-training-attendance],body.ot-navigation.ot-builder-active [data-save-training-day],body.ot-navigation.ot-builder-active [data-complete-training],body.ot-navigation .members-profile-page #trainingCopyPanel{display:none!important}
body.ot-navigation #schema-builder .training-builder{grid-template-columns:minmax(100px,.7fr) minmax(0,2fr) minmax(180px,1fr)}
body.ot-navigation #schema-builder .training-form{grid-template-columns:repeat(2,minmax(0,1fr))}
body.ot-navigation .training-exercise,body.ot-navigation .exercise-card,body.ot-navigation .training-session-area{min-width:0;max-width:100%}
body.ot-navigation #ot-dashboard-reminders:empty,body.ot-navigation #ot-agenda-reminders:empty{display:none}
body.ot-navigation .ot-menu-toggle{display:none!important}
@media(max-width:1150px){body.ot-navigation{--ot-rail:160px}body.ot-navigation .content{padding:14px!important}body.ot-navigation .topbar{padding:10px 14px!important}body.ot-navigation .members-profile-page{padding:12px}body.ot-navigation #schema-builder .training-builder{grid-template-columns:1fr}}
@media(max-width:760px){body.ot-navigation{--ot-rail:148px}body.ot-navigation .members-profile-tabs [role=tab]{flex-basis:calc(20% - 5px)}body.ot-navigation .ot-main-nav .nav-btn{font-size:12px;padding:9px 5px}body.ot-navigation .content{padding:10px!important}}
@media(max-width:650px){body.ot-navigation{--ot-top:112px}body.ot-navigation .app-shell{grid-template-columns:minmax(0,1fr)!important}body.ot-navigation .topbar{grid-column:1;position:relative!important;top:auto!important;padding:10px!important}body.ot-navigation .content{grid-column:1;padding:10px!important}body.ot-navigation .sidebar{display:none!important;position:fixed!important;top:var(--ot-top)!important;left:0!important;width:190px!important;height:calc(100dvh - var(--ot-top))!important;z-index:80;box-shadow:10px 0 30px #0008}body.ot-navigation.ot-sidebar-open .sidebar{display:block!important}body.ot-navigation .ot-menu-toggle{display:block!important;order:0;align-self:center}body.ot-navigation .ot-members-search{min-width:180px;flex-basis:200px}body.ot-navigation .topbar-controls{justify-content:flex-start;margin:0}body.ot-navigation .members-profile-tabs [role=tab]{flex-basis:calc(33.333% - 5px)}body.ot-navigation #schema-builder .training-form{grid-template-columns:1fr}body.ot-navigation .members-profile-page{padding:10px}}

body.ot-navigation.fmz-owner-test-active{padding-top:var(--ot-top)!important}
body.ot-navigation .ot-menu-close,body.ot-navigation .ot-tools-toggle{display:none!important}
@media(max-width:1000px){body.ot-navigation .ot-tools-toggle{display:block!important;order:2;align-self:center;min-height:40px}body.ot-navigation:not(.ot-tools-open) .topbar-controls{display:none!important}body.ot-navigation.ot-tools-open .topbar-controls{flex-basis:100%;order:3}}
@media(max-width:650px){body.ot-navigation .ot-menu-close{display:block!important;width:100%;margin-bottom:12px}}

html.ot-navigation-root{scroll-padding-top:calc(var(--ot-top,74px) + var(--ot-header-height,80px) + 12px)}
body.ot-navigation .ot-schema-copy{display:grid;gap:16px;margin-bottom:20px;min-width:0}
body.ot-navigation .ot-schema-copy[hidden]{display:none}
body.ot-navigation .ot-schema-copy .field{display:grid;gap:8px;max-width:700px}
body.ot-navigation .ot-copy-plan{display:grid;gap:14px;padding-left:24px}
body.ot-navigation .ot-copy-plan li{min-width:0;overflow-wrap:anywhere}
body.ot-navigation .ot-copy-plan img{display:block;width:180px;max-width:100%;height:130px;object-fit:contain;border-radius:8px}
body.ot-navigation .ot-schema-copy .ot-selected-member{margin:12px 0}
body.ot-navigation .ot-schema-copy select{max-width:100%;width:100%;white-space:normal}
body.ot-navigation #schema-builder .view-head{flex-wrap:wrap;gap:12px}
body.ot-navigation .ot-copy-history-row{min-width:0;overflow-wrap:anywhere;padding:12px 0;border-bottom:1px solid var(--line)}
body.ot-navigation .ot-copy-history-row summary{cursor:pointer;padding:10px 0}
body.ot-navigation #schema-builder [hidden]{display:none!important}

.ot-status-card,.ot-calendar{border:1px solid var(--ot-border);background:var(--ot-surface);color:var(--ot-text);border-radius:14px;padding:16px;margin:16px 0;min-width:0;overflow-wrap:anywhere}
.ot-status-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.ot-status-heading>strong{color:var(--ot-gold)}.ot-status-card p{color:var(--ot-muted);line-height:1.5}.ot-status-card summary{cursor:pointer;min-height:44px;display:flex;align-items:center}.ot-status-card article{border-top:1px solid var(--ot-border);padding:12px 0}
.ot-status-dialog textarea{width:100%;box-sizing:border-box;font:inherit;color:var(--ot-text);background:var(--ot-surface);border:1px solid var(--ot-border);border-radius:8px;padding:10px}.ot-status-dialog fieldset{border:1px solid var(--ot-border);border-radius:8px}.ot-status-warning{border-left:3px solid var(--ot-gold);padding:12px;line-height:1.5}
.ot-calendar-controls{display:flex;gap:8px;flex-wrap:wrap;align-items:end;margin:12px 0}.ot-calendar-controls label{display:grid;gap:5px;flex:1 1 150px}.ot-calendar-controls input,.ot-calendar-controls select{min-height:44px;min-width:0;width:100%;color:var(--ot-text);background:var(--ot-surface);border:1px solid var(--ot-border);border-radius:8px;padding:8px;font:inherit}.ot-calendar button{min-height:44px;border:1px solid var(--ot-border);background:var(--ot-surface);color:var(--ot-text);border-radius:8px;padding:8px 12px;font:inherit;cursor:pointer}.ot-calendar button:focus-visible{outline:3px solid var(--ot-focus);outline-offset:3px}.ot-calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}.ot-calendar-cell{min-width:0;border:1px solid var(--ot-border);border-radius:8px;padding:7px;min-height:90px}.ot-calendar-cell>strong{display:block;margin-bottom:8px}.ot-calendar-cell button{width:100%;text-align:left;font-size:.85rem;padding:7px;overflow-wrap:anywhere;white-space:normal;margin:4px 0}.ot-calendar-cell button[data-overdue=true]{border-left:3px solid var(--ot-gold)}.ot-calendar-list article{padding:12px 0;border-bottom:1px solid var(--ot-border)}.ot-calendar-list p{line-height:1.45}.ot-calendar-notice{color:var(--ot-muted)}
@media(max-width:800px){.ot-calendar-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ot-calendar-cell{min-height:70px}}@media(max-width:420px){.ot-calendar-grid{grid-template-columns:1fr}}

.ot-calendar-grid[data-calendar-view=day]{grid-template-columns:1fr}

/* Only loaded in the synthetic owner-test. No production API or database migration. */
(function(root){
 'use strict';
 const copy=value=>structuredClone(value),text=value=>typeof value==='string'||typeof value==='number'?String(value):'';
 const fields=['day','exercise','sets','reps','rest','tempo','group','equipment','image','targetRir','targetRpe','targetRIR','targetRPE','rirTarget','rpeTarget','schemaInstructions','generalInstructions'];
 const sha=async value=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(value)))),x=>x.toString(16).padStart(2,'0')).join('');
 function structure(entries){return (Array.isArray(entries)?entries:[]).map(entry=>Object.fromEntries(fields.filter(key=>Object.hasOwn(entry,key)).map(key=>[key,text(entry[key])])));}
 function valid(entries){if(!entries.length)throw Error('Dit schema bevat geen oefeningen.');for(const e of entries)if(!e.exercise?.trim()||!['Maandag','Dinsdag','Woensdag','Donderdag','Vrijdag','Zaterdag','Zondag'].includes(e.day)||!/^\d+$/.test(e.sets)||Number(e.sets)<1||Number(e.sets)>100||!e.reps?.trim())throw Error('Controleer trainingsdag, oefening, sets en herhalingen.');}
 function createService(adapter,hooks){
  let queue=Promise.resolve();const serial=fn=>{const job=queue.catch(()=>{}).then(fn);queue=job;return job;};
  function authorize(){const s=adapter.getState();if(s.synthetic!==true||s.closed||s.fakeActor!=='trainer')throw Error('Alleen de aangemelde synthetische trainer kan schema’s kopiëren.');return s;}
  function data(){authorize();return copy(adapter.getState().guide.schemaCopies||{version:1,versions:[],operations:[]});}
  async function write(value,patch={}){authorize();if(adapter.patchGuide)await adapter.patchGuide({...patch,schemaCopies:value});else await adapter.setGuide({...adapter.getState().guide,...patch,schemaCopies:value});authorize();}
  async function member(id,coaching=false){authorize();const profile=await hooks.profile(id);authorize();const c=hooks.clients().find(x=>x.id===id);if(!c||profile.member?.client_id!==id)throw Error('Dit lid is niet toegankelijk.');if(coaching&&adapter.memberStatusRead){const status=await adapter.memberStatusRead(id);authorize();if(!status[0]?.coaching)throw Error('Nieuwe coaching is voor dit lid gepauzeerd.');}return c;}
  async function versions(id){return serial(async()=>{const c=await member(id),d=data(),groups=new Map();for(const entry of c.trainingPlan||[]){const key=entry.schemaId||entry.schemaName||'Trainingsschema';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(entry);}let changed=false;for(const [key,rows]of groups){const plan=structure(rows),hash=await sha(plan);if(!d.versions.some(v=>v.memberId===id&&v.key===key&&v.hash===hash)){d.versions.push({id:crypto.randomUUID(),memberId:id,key,name:rows[0].schemaName||'Trainingsschema',hash,number:1+d.versions.filter(v=>v.memberId===id&&v.key===key).length,recordedAt:new Date().toISOString(),plan});changed=true;}}if(changed)await write(d);return copy(d.versions.filter(v=>v.memberId===id));});}
